import Link from 'next/link';

export default function Forbidden() {
  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      minHeight: '100vh',
      fontFamily: 'system-ui, sans-serif',
      color: '#333',
      textAlign: 'center',
      padding: '20px'
    }}>
      <h1 style={{ fontSize: '4rem', margin: '0', color: '#e00' }}>403</h1>
      <h2 style={{ fontSize: '2rem', margin: '10px 0 20px 0' }}>Access Forbidden</h2>
      <p style={{ fontSize: '1.2rem', maxWidth: '500px', margin: '0 0 30px 0', lineHeight: '1.5' }}>
        Sorry, you don't have permission to access this page. This area is restricted to administrators only.
      </p>
      <Link href="/" style={{
        padding: '12px 24px',
        backgroundColor: '#0070f3',
        color: 'white',
        textDecoration: 'none',
        borderRadius: '6px',
        fontWeight: '600',
        transition: 'background-color 0.2s'
      }}>
        Return to Home
      </Link>
    </div>
  );
}

